def evaluate(current_reputation, observation, my_history, round_num):
    # Use recent_window to determine the majority action among recent observations.
    # Update reputation more strongly if the observed action goes against the majority.
    recent = observation.get('recent_window', [])
    if recent:
        coop_count = sum(1 for o in recent if o['action'] == 'cooperate')
        majority_cooperate = coop_count > len(recent) / 2
    else:
        majority_cooperate = None  # no prior information

    action = observation['action']
    if majority_cooperate is None:
        # No majority: use symmetric step
        step = 0.2 if action == 'cooperate' else -0.2
    elif majority_cooperate:
        # Majority cooperated: punish defectors extra, slightly reward cooperators
        step = 0.1 if action == 'cooperate' else -0.4
    else:
        # Majority defected: reward cooperators extra, slightly punish defectors
        step = 0.4 if action == 'cooperate' else -0.1

    new_rep = current_reputation + step
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Compute personal cooperation rate from own history.
    if my_history:
        coop_count = sum(1 for d in my_history if d['action'] == 'cooperate')
        coop_rate = coop_count / len(my_history)
    else:
        coop_rate = 0.5

    # Base threshold determined by past behavior:
    # if defecting a lot, become more cooperative (lower threshold);
    # if cooperating a lot, become more cautious (higher threshold).
    if coop_rate < 0.3:
        threshold = -0.2
    elif coop_rate > 0.7:
        threshold = 0.1
    else:
        threshold = 0.0

    # Early rounds: be more cautious (increase threshold)
    if round_num < 5:
        threshold += 0.15

    return recipient_reputation > threshold

