def decide(recipient_reputation, round_num, my_history):
    # More forgiving baseline threshold
    if round_num <= 3:
        threshold = 0.0
    elif round_num > 10:
        threshold = -0.3
    else:
        threshold = 0.0

    # Consider own recent behavior: last 3 rounds
    if my_history:
        recent = my_history[-3:]  # last 3 actions (or fewer)
        defection_count = sum(1 for d in recent if d["action"] == "defect")

        # If we have defected recently, become less forgiving (more cautious)
        if defection_count >= 1:
            threshold += 0.2
        # If we have cooperated in all recent rounds, become more forgiving
        else:
            threshold -= 0.1

    # Additionally, if we have a long history of cooperation overall,
    # slightly reduce threshold further (but only if we have at least 10 rounds)
    if len(my_history) >= 10:
        total_coop = sum(1 for d in my_history if d["action"] == "cooperate")
        coop_ratio = total_coop / len(my_history)
        if coop_ratio > 0.7:
            threshold -= 0.15

    return recipient_reputation > threshold

