_state = {
    "personal_trust": 0.0,          # running average of observed cooperativeness
    "trust_count": 0,               # number of observations used
    "rounds": 0                     # total rounds played
}

def evaluate(current_reputation, observation, my_history, round_num):
    # Update personal trust from recent observations
    recent = observation.get("recent_window", [])
    if recent:
        sum_obs = 0.0
        for entry in recent:
            if entry["action"] == "cooperate":
                sum_obs += 1.0
            else:
                sum_obs -= 1.0
        obs_avg = sum_obs / len(recent)
        # Update running average (exponential smoothing with window count)
        alpha = 0.1
        _state["personal_trust"] = (1 - alpha) * _state["personal_trust"] + alpha * obs_avg
        _state["trust_count"] += 1
    else:
        obs_avg = 0.0  # no observations, neutral

    # Update new reputation based on observed avg and current reputation
    # Use a decay factor for old reputation
    new_rep = current_reputation * 0.8 + obs_avg * 0.2
    # Clamp to [-1, 1]
    new_rep = max(-1.0, min(1.0, new_rep))
    return new_rep

def decide(recipient_reputation, round_num, my_history):
    # Use recipient_reputation (from other agents' evaluations) and personal trust
    threshold = 0.2
    # Also require a minimum of observations to trust others
    if _state["trust_count"] < 3:
        return False  # be cautious initially
    # Cooperate only if recipient has good reputation and the agent's personal trust is not too low
    if recipient_reputation > threshold and _state["personal_trust"] > -0.3:
        return True
    else:
        return False
